case VNType::atCover: {
    const AstCover* const currp = static_cast<const AstCover*>(this);
    // Checking op1p
    UASSERT_OBJ(currp->propp(), currp, "AstCover must have non nullptr propp()");
    UASSERT_OBJ(!currp->propp()->nextp(), currp, "AstCover::propp() cannot have a non nullptr nextp()");
    currp->propp()->checkTreeIter(currp);
    // Checking op2p
    if (AstSenTree* const opp = currp->sentreep()) {
        UASSERT_OBJ(!currp->sentreep()->nextp(), currp, "AstCover::sentreep() cannot have a non nullptr nextp()");
        opp->checkTreeIter(currp);
    }
    // Checking op3p
    if (const AstNode* const headp = currp->coverincsp()) {
        const AstNode* backp = currp;
        const AstNode* tailp = headp;
        const AstNode* opp = headp;
        do {
            opp->checkTreeIter(backp);
            UASSERT_OBJ(opp == headp || !opp->nextp() || !opp->m_headtailp, opp, "Headtailp should be null in middle of lists");
            backp = tailp = opp;
            opp = opp->nextp();
        } while (opp);
        // cppcheck-suppress knownConditionTrueFalse
        if (false && headp && tailp) {}  // Prevent unused
        UASSERT_OBJ(headp->m_headtailp == tailp, headp, "Tail in headtailp is inconsistent");
        UASSERT_OBJ(tailp->m_headtailp == headp, tailp, "Head in headtailp is inconsistent");
    }
    // Checking op4p
    if (const AstNode* const headp = currp->passsp()) {
        const AstNode* backp = currp;
        const AstNode* tailp = headp;
        const AstNode* opp = headp;
        do {
            opp->checkTreeIter(backp);
            UASSERT_OBJ(opp == headp || !opp->nextp() || !opp->m_headtailp, opp, "Headtailp should be null in middle of lists");
            backp = tailp = opp;
            opp = opp->nextp();
        } while (opp);
        // cppcheck-suppress knownConditionTrueFalse
        if (false && headp && tailp) {}  // Prevent unused
        UASSERT_OBJ(headp->m_headtailp == tailp, headp, "Tail in headtailp is inconsistent");
        UASSERT_OBJ(tailp->m_headtailp == headp, tailp, "Head in headtailp is inconsistent");
    }
    break;
}
